// === Tab: mySketch ===
let pg,pg2,pg3,pg4;
let color0;
let theShader1;
let theShader2;
let tex;

function setup() {
  createCanvas(800, 800, WEBGL);
  background(5, 10, 30); // deep dark blue
  noStroke();

  pg = createGraphics(width, height);
  image_init(pg);
  pg2 = createGraphics(width, height);
  image_init(pg2);
  pg3 = createGraphics(width, height);
  image_init(pg3);
  pg4 = createGraphics(width, height);
  image_init(pg4);

  // Changed: deep cyan as base color instead of beige
  color0 = rand_color('#00F5FF');
  theShader1 = createShader(shader1.vs, shader1.fs);
  theShader2 = createShader(shader1.vs, frag_glith);

  const n = 100;
  translate(-width/2, -height/2);

  widthGrid_pg1(pg, 10);
  widthGrid(pg2, n, 0.5);
  widthGrid(pg3, 10, 0.7);
  widthStripe(pg4, n, 0.5);

  shader(theShader1);
  theShader1.setUniform(`u_tex`, pg);
  theShader1.setUniform(`u_tex2`, pg2);
  theShader1.setUniform(`u_tex3`, pg3);
  theShader1.setUniform(`u_tex4`, pg4);
  theShader1.setUniform('u_color', color0);
  theShader1.setUniform(`u_time`, frameCount / 200);
  rect(0, 0, width, height);

  resetShader();
  tex = get(0, 0, width, height);
  describe('Cyberpunk glitch animation with cyan and purple tones by Ariel Poghon.');
}

function draw() {
  translate(-width/2, -height/2);
  if (frameCount > 200) {
    clear();
    shader(theShader2);
    theShader2.setUniform(`u_tex`, tex);
    theShader2.setUniform(`u_time`, frameCount / 200);
    rect(0, 0, width, height);
  }
}

const image_init = (pg) => {
  pg.rectMode(CENTER);
  pg.fill("#000000");
  pg.noStroke();
};

const widthGrid = (pg, num, size) => {
  pg.push();
  pg.fill(255);
  pg.rect(0, 0, pg.width*2, pg.height*2);
  pg.fill(0);
  pg.pop();
  const w = width/num;
  const w2 = w*size;
  for (let i = 0; i < num; i++) {
    for (let j = 0; j < num; j++) {
      pg.push();
      pg.translate(i*w + w/2, j*w + w/2);
      pg.rect(0, 0, w2, w2);
      pg.pop();
    }
  }
};

const widthStripe = (pg, num, size) => {
  pg.push();
  pg.fill(255);
  pg.rect(0, 0, pg.width*2, pg.height*2);
  pg.fill(0);
  pg.pop();
  var w = width/num;
  var w2 = w*size;
  for (let j = 0; j < num; j++) {
    pg.push();
    pg.translate(0, j*w + w/2);
    pg.rect(0, 0, pg.width*2, w2);
    pg.pop();
  }
};

const widthGrid_pg1 = (pg, num) => {
  var w = width/num;
  for (let i = 0; i < num; i++) {
    for (let j = 0; j < num; j++) {
      if ((i % 2 === 0 && j % 2 === 0) || (i % 2 === 1 && j % 2 === 1)) {
        // Changed: cyan and purple instead of white/grey
        if (random(1) < 0.5) {
          pg.fill('#00F5FF'); // cyan
        } else {
          pg.fill('#7B2FBE'); // purple
        }
      } else {
        if (random(1) < 0.5) {
          pg.fill('#0A0A2E'); // deep navy
        } else {
          pg.fill('#FF2079'); // hot pink accent
        }
      }
      pg.rect(i*w + w/2, j*w + w/2, w, w);
    }
  }
};

const rects = (pg, w) => {
  pg.rect(0, 0, w, w);
};

const rand_color = (colorCode) => {
  let rc = color(colorCode);
  return [red(rc)/255.0, green(rc)/255.0, blue(rc)/255.0];
};

const shader1 = {
  vs: `
  precision highp float;
  precision highp int;
  attribute vec3 aPosition;
  attribute vec2 aTexCoord;
  varying vec2 vTexCoord;
  uniform mat4 uProjectionMatrix;
  uniform mat4 uModelViewMatrix;
  void main() {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vTexCoord = aTexCoord;
  }`,
  fs: `
  precision highp float;
  precision highp int;
  varying vec2 vTexCoord;
  uniform sampler2D u_tex;
  uniform sampler2D u_tex2;
  uniform sampler2D u_tex3;
  uniform sampler2D u_tex4;
  uniform float u_time;
  uniform vec3 u_color;
  float PI = 3.14159265358979;
  float random(vec2 c){
    return fract(sin(dot(c.xy, vec2(12.9898,78.233))) * 43758.5453);
  }
  void main() {
    vec2 uv = vTexCoord;
    vec4 tex = texture2D(u_tex2, uv);
    vec4 tex3 = texture2D(u_tex3, uv);
    vec4 tex4 = texture2D(u_tex4, uv);
    vec4 tex_lattice = texture2D(u_tex, uv);
    if (tex_lattice == vec4(u_color, 1.0)) {
      gl_FragColor = tex;
    } else if (tex_lattice == vec4(1.0, 1.0, 1.0, 1.0)) {
      gl_FragColor = tex4;
    } else if (tex_lattice == vec4(1.0, 1.0, 1.0, 0.0)) {
      gl_FragColor = tex3;
    } else {
      gl_FragColor = tex_lattice;
    }
    // increased noise for more aggressive glitch feel
    float interval = 3.0;
    float strength = smoothstep(interval * 0.5, interval, interval - mod(0.0, interval));
    float whiteNoise = (random(uv + mod(0.0, 10.0)) * 2.0 - 1.0) * (0.25 + strength * 0.25);
    gl_FragColor = gl_FragColor + whiteNoise;
  }`
};

const frag_glith = `
  precision highp float;
  precision highp int;
  varying vec2 vTexCoord;
  uniform sampler2D u_tex;
  uniform float u_time;
  float PI = 3.14159265358979;
  // Increased glitch rate for more intensity
  #define RATE 0.003
  float rand(vec2 co){
    return fract(sin(dot(co.xy, vec2(12.9898,78.233))) * 43758.5453) * 2.0 - 1.0;
  }
  float offset(float blocks, vec2 uv) {
    float shaderTime = u_time * RATE;
    return rand(vec2(shaderTime, floor(uv.y * blocks)));
  }
  void main() {
    vec2 uv = vTexCoord;
    // Wider RGB split for stronger chromatic aberration
    gl_FragColor.r = texture2D(u_tex, uv + vec2(offset(64.0, uv) * 0.06, 0.0)).r;
    gl_FragColor.g = texture2D(u_tex, uv + vec2(offset(64.0, uv) * 0.01, 0.0)).g;
    gl_FragColor.b = texture2D(u_tex, uv + vec2(offset(42.0, uv) * 0.06, 0.0)).b;
    gl_FragColor.a = 1.0;
  }
`;

